// Wire compatibility for the stage instance to stage run rename. Records written
// before the rename carry the legacy key. It is accepted on input until
// release 15, and new records never write it.
export const LEGACY_KEYS: Readonly<Record<string, string>> = {
  stage_instance_id: "stage_run_id",
};

export function readLegacyKeys(
  record: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(record)) {
    const current = LEGACY_KEYS[key];
    if (current === undefined) result[key] = value;
    else if (!(current in record)) result[current] = value;
  }
  return result;
}

