const envelope = (artifact_id: string, artifact_type: string, output_name: string, unit_id: string, body: JsonValue): ArtifactEnvelope => ({
  artifact_id: artifact_id as ArtifactId,
  artifact_type,
  output_name,
  unit_id: unit_id as UnitId,
  body,
