  const web: MaterializedExecutionUnit = { unit_id: "web" as UnitId, parameters: { unit_id: "web", artifact: briefBody }, depends_on: ["foundation" as UnitId] };
  const inputs = { brief: [brief], repository_refs: repositoryRefs };
